-- ProyectoGrupal - version PostgreSQL (Supabase / Render)
-- Ejecutar entero en el SQL Editor de Supabase. Se puede relanzar: borra y recrea las tablas.
-- Cambios respecto a MySQL:
--   * Sin CREATE DATABASE / USE: Supabase ya da la base "postgres" (esquema public).
--   * AUTO_INCREMENT -> GENERATED BY DEFAULT AS IDENTITY.
--   * Sin comillas invertidas en los nombres de columna.
--   * Los nombres en camelCase (alumnosProyectos...) PostgreSQL los guarda en minusculas.
--   * Al final se reajustan los contadores de los id, porque los INSERT llevan id explicito.
-- Los INSERT se generan desde data/clase_1..4.csv y data/claustro.csv.

BEGIN;

DROP TABLE IF EXISTS promocionClaustro, claustro, promocionProyectos, alumnosPromocion,
    alumnosProyectos, proyectos, alumnos, promocion CASCADE;

CREATE TABLE promocion (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    año INTEGER,
    fecha_comienzo DATE,
    campus VARCHAR(20),
    vertical VARCHAR(5)
);
CREATE TABLE alumnos (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre VARCHAR(20),
    email TEXT
);

CREATE TABLE proyectos (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre VARCHAR(20)
);
CREATE TABLE alumnosProyectos (
    id_alumnos INTEGER,
    id_proyectos INTEGER,
    evaluacion VARCHAR(20),
    PRIMARY KEY (id_alumnos, id_proyectos),
    FOREIGN KEY (id_alumnos) REFERENCES alumnos(id),
    FOREIGN KEY (id_proyectos) REFERENCES proyectos(id)
);
CREATE TABLE alumnosPromocion (
    id_promocion INTEGER,
    id_alumnos INTEGER,
    PRIMARY KEY (id_promocion, id_alumnos),
    FOREIGN KEY (id_alumnos) REFERENCES alumnos(id),
    FOREIGN KEY (id_promocion) REFERENCES promocion(id)
);
CREATE TABLE promocionProyectos (
    id_promocion INTEGER,
    id_proyectos INTEGER,
    PRIMARY KEY (id_promocion, id_proyectos),
    FOREIGN KEY (id_promocion) REFERENCES promocion(id),
    FOREIGN KEY (id_proyectos) REFERENCES proyectos(id)
);
CREATE TABLE claustro (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre VARCHAR(30),
    rol VARCHAR(20),
    -- En MySQL era ENUM("presencial","online"); PostgreSQL no admite ENUM dentro del CREATE TABLE.
    modalidad VARCHAR(20) CHECK (modalidad IN ('presencial', 'online'))
);
CREATE TABLE promocionClaustro (
    id_claustro INTEGER,
    id_promocion INTEGER,
    PRIMARY KEY (id_claustro, id_promocion),
    FOREIGN KEY (id_claustro) REFERENCES claustro(id),
    FOREIGN KEY (id_promocion) REFERENCES promocion(id)
);

-- 1. Promociones (6): las de clase_1..4 y las que solo aparecen en claustro.

-- 2. Proyectos (10): nombres tal como vienen en las cabeceras de los CSV.

-- 3. Alumnos (52). La promocion va en alumnosPromocion (N:M).

-- 4. Relacion N:M alumnos-promocion (52).

-- 5. Relacion promociones-proyectos (20).

-- 6. Evaluaciones de cada alumno en sus proyectos (260).

-- 7. Claustro (10), con su modalidad en minusculas como en el ENUM.

-- 8. Relacion claustro-promocion (10).

-- 9. Reajustar los contadores de identidad tras insertar los id a mano.
SELECT setval(pg_get_serial_sequence('promocion', 'id'), (SELECT MAX(id) FROM promocion));
SELECT setval(pg_get_serial_sequence('alumnos', 'id'), (SELECT MAX(id) FROM alumnos));
SELECT setval(pg_get_serial_sequence('proyectos', 'id'), (SELECT MAX(id) FROM proyectos));
SELECT setval(pg_get_serial_sequence('claustro', 'id'), (SELECT MAX(id) FROM claustro));

COMMIT;

-- Comprobacion: numero de filas por tabla.
-- Esperado: promocion 6, alumnos 52, proyectos 10, alumnosPromocion 52,
-- promocionProyectos 20, alumnosProyectos 260, claustro 10, promocionClaustro 10.
SELECT 'promocion' AS tabla, COUNT(*) AS filas FROM promocion
UNION ALL SELECT 'alumnos', COUNT(*) FROM alumnos
UNION ALL SELECT 'proyectos', COUNT(*) FROM proyectos
UNION ALL SELECT 'alumnosPromocion', COUNT(*) FROM alumnosPromocion
UNION ALL SELECT 'promocionProyectos', COUNT(*) FROM promocionProyectos
UNION ALL SELECT 'alumnosProyectos', COUNT(*) FROM alumnosProyectos
UNION ALL SELECT 'claustro', COUNT(*) FROM claustro
UNION ALL SELECT 'promocionClaustro', COUNT(*) FROM promocionClaustro;

-- Ejemplo: alumnos de cada promocion con sus notas (pasando por la tabla N:M).
SELECT a.nombre, pr.vertical, pr.campus, pr.fecha_comienzo, p.nombre AS proyecto, ap.evaluacion
FROM alumnos a
    INNER JOIN alumnosPromocion apr ON a.id = apr.id_alumnos
    INNER JOIN promocion pr ON apr.id_promocion = pr.id
    INNER JOIN alumnosProyectos ap ON a.id = ap.id_alumnos
    INNER JOIN proyectos p ON ap.id_proyectos = p.id
WHERE a.nombre LIKE 'Jafet%';
